package org.example.backend.config;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import org.junit.jupiter.api.Test;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import jakarta.servlet.FilterChain;

class HttpFilterBehaviorTest {
    @Test void securityHeadersAreAppliedAfterDownstreamAndSensitiveResponsesDisableCaching() throws Exception{
        for(String uri:new String[]{"/auth/profile","/admin/users","/users","/labs"}){
            MockHttpServletRequest request=new MockHttpServletRequest("GET",uri);MockHttpServletResponse response=new MockHttpServletResponse();
            new SecurityHeadersFilter(true).doFilter(request,response,(req,res)->((MockHttpServletResponse)res).setHeader("X-Frame-Options","bad"));
            assertEquals("SAMEORIGIN",response.getHeader("X-Frame-Options"));assertEquals("nosniff",response.getHeader("X-Content-Type-Options"));assertEquals("frame-ancestors 'self'",response.getHeader("Content-Security-Policy"));
            if(uri.equals("/labs"))assertNull(response.getHeader("Cache-Control"));else assertTrue(response.getHeader("Cache-Control").contains("no-store"));
        }
        MockHttpServletResponse disabled=new MockHttpServletResponse();new SecurityHeadersFilter(false).doFilter(new MockHttpServletRequest("GET","/users"),disabled,(req,res)->res.getWriter().write("ok"));assertEquals("ok",disabled.getContentAsString());assertNull(disabled.getHeader("X-Frame-Options"));
    }
    @Test void requestsWithoutOriginPassWhileForeignOriginsReceiveJsonDenial() throws Exception{StrictCorsFilter filter=new StrictCorsFilter("https://school.test, ,https://admin.test","http://localhost:*");FilterChain chain=mock(FilterChain.class);MockHttpServletRequest local=new MockHttpServletRequest("GET","/labs");MockHttpServletResponse localResponse=new MockHttpServletResponse();filter.doFilter(local,localResponse,chain);verify(chain).doFilter(local,localResponse);MockHttpServletRequest foreign=new MockHttpServletRequest("GET","/labs");foreign.addHeader("Origin","https://evil.test");MockHttpServletResponse response=new MockHttpServletResponse();filter.doFilter(foreign,response,chain);assertEquals(403,response.getStatus());assertTrue(response.getContentAsString().contains("CORS origin is not allowed"));verify(chain,times(1)).doFilter(any(),any());}
    @Test void allowedPreflightReturnsHeadersWithoutExecutingBusinessChain() throws Exception{StrictCorsFilter filter=new StrictCorsFilter(null,"http://localhost:*");FilterChain chain=mock(FilterChain.class);MockHttpServletRequest request=new MockHttpServletRequest("OPTIONS","/labs");request.addHeader("Origin","http://localhost:5173");request.addHeader("Access-Control-Request-Method","PUT");MockHttpServletResponse response=new MockHttpServletResponse();filter.doFilter(request,response,chain);assertEquals(204,response.getStatus());assertEquals("http://localhost:5173",response.getHeader("Access-Control-Allow-Origin"));assertEquals("PUT",response.getHeader("Access-Control-Allow-Methods"));assertEquals("X-Request-Id",response.getHeader("Access-Control-Expose-Headers"));assertNull(response.getHeader("Access-Control-Allow-Credentials"));verifyNoInteractions(chain);}
    @Test void normalCorsResponsesReapplyHeadersAfterDownstreamChanges() throws Exception{StrictCorsFilter filter=new StrictCorsFilter("https://school.test","");MockHttpServletRequest request=new MockHttpServletRequest("GET","/labs");request.addHeader("Origin","https://school.test");MockHttpServletResponse response=new MockHttpServletResponse();filter.doFilter(request,response,(req,res)->{((MockHttpServletResponse)res).setHeader("Access-Control-Allow-Origin","bad");res.getWriter().write("ok");});assertEquals("ok",response.getContentAsString());assertEquals("https://school.test",response.getHeader("Access-Control-Allow-Origin"));assertTrue(response.getHeader("Access-Control-Allow-Methods").contains("GET"));}
    @Test void requestLoggingMasksSecretsLimitsUntrustedTextAndCleansMdcAfterFailure() throws Exception{Logger logger=(Logger)LoggerFactory.getLogger(RequestLoggingFilter.class);ListAppender<ILoggingEvent> appender=new ListAppender<>();appender.start();logger.addAppender(appender);try{RequestLoggingFilter filter=new RequestLoggingFilter();MockHttpServletRequest request=new MockHttpServletRequest("GET","/labs");request.addHeader("X-Request-Id","test-request");request.addHeader("X-Forwarded-For","10.0.0.1, 10.0.0.2");request.addHeader("User-Agent","u".repeat(200));request.setQueryString("token=secret-token&password=secret-password&secret=secret-value&apiKey=key-value&authorization=bearer-value&flag&query="+"x".repeat(200));MockHttpServletResponse response=new MockHttpServletResponse();assertThrows(jakarta.servlet.ServletException.class,()->filter.doFilter(request,response,(req,res)->{assertEquals("test-request",MDC.get("requestId"));throw new jakarta.servlet.ServletException("downstream");}));assertEquals("test-request",response.getHeader("X-Request-Id"));assertNull(MDC.get("requestId"));String message=appender.list.get(0).getFormattedMessage();assertTrue(message.contains("token=******"));assertTrue(message.contains("password=******"));assertTrue(message.contains("flag"));assertTrue(message.contains("ip=10.0.0.1"));assertFalse(message.contains("secret-token"));assertFalse(message.contains("secret-password"));assertFalse(message.contains("u".repeat(161)));assertEquals(2,appender.list.size());}finally{logger.detachAppender(appender);appender.stop();}}
    @Test void loggingCreatesRequestIdsAndHandlesRealIpRemoteIpAndEmptyQueries() throws Exception{RequestLoggingFilter filter=new RequestLoggingFilter();for(String header:new String[]{"X-Real-IP",null}){MockHttpServletRequest request=new MockHttpServletRequest("GET","/health");if(header!=null)request.addHeader(header,"10.0.0.3");MockHttpServletResponse response=new MockHttpServletResponse();filter.doFilter(request,response,(req,res)->assertNotNull(MDC.get("requestId")));assertTrue(response.getHeader("X-Request-Id").matches("[0-9a-f]{32}"));assertNull(MDC.get("requestId"));}}
}
